"""Writers for the generated voice SRC coefficient files."""
from pathlib import Path

import numpy as np

LICENCE = "// This Software is subject to the terms of the XMOS Public Licence: Version 1."

AUTOGEN_BANNER = """\
/*********************************/
/* AUTOGENERATED. DO NOT MODIFY! */
/*********************************/

// Use lib_src.voice.generate to regenerate this file
// {cmd}"""

ALIGNMENT_MACRO = """\
#ifndef ALIGNMENT
#  ifdef __xcore__
#    define ALIGNMENT(N)  __attribute__((aligned (N)))
#  else
#    define ALIGNMENT(N)
#  endif
#endif"""


def _copyright(years):
    return f"// Copyright {years} XMOS LIMITED.\n{LICENCE}"


def format_array_1d(values, per_line=6):
    """Format values as C initialiser lines, ``per_line`` values per line."""
    out = ''
    for i, v in enumerate(values):
        out += ' ' + str(int(v)).rjust(12) + ','
        if ((i + 1) % per_line) == 0:
            out += '\n'
    return out


def format_array_2d(values, per_line=6):
    """Format a 2D array as nested C initialiser blocks, one block per row."""
    out = ''
    for row in values:
        out += '    {\n    '
        for i, v in enumerate(row):
            out += ' ' + str(int(v)).rjust(12) + ','
            if ((i + 1) % per_line) == 0:
                out += '\n    '
        out += '},\n'
    return out


def write_ff3_files(output_dir, name, taps_q31, coefs_q30, cmd, years="2023-2026"):
    """
    Write ``<name>_coefs.h`` and ``<name>_coefs.c`` for the VPU ff3 SRC.

    ``taps_q31`` is the flat prototype used for debugging, ``coefs_q30`` is the
    ``[num_phases][taps_per_phase]`` polyphase table.
    """
    num_phases, taps_per_phase = np.shape(coefs_q30)
    name_up = name.upper()
    banner = AUTOGEN_BANNER.format(cmd=cmd)

    header = f"""\
{_copyright(years)}

{banner}

#pragma once

#include <stdint.h>

{ALIGNMENT_MACRO}

#define {name_up}_NUM_PHASES ({num_phases})
#define {name_up}_TAPS_PER_PHASE ({taps_per_phase})

/** q31 coefficients to use for debugging ff3 sample rate conversion */
extern const int32_t {name}_coefs_debug[{name_up}_NUM_PHASES * {name_up}_TAPS_PER_PHASE];

/** q30 coefficients to use for the ff3 48 - 16 kHz polyphase FIR filtering */
extern const int32_t {name}_coefs[{name_up}_NUM_PHASES][{name_up}_TAPS_PER_PHASE];

"""

    source = f"""\
{_copyright(years)}

{banner}

#include "{name}_coefs.h"
#include <stdint.h>

/** q31 coefficients to use for debugging ff3 sample rate conversion */
const int32_t ALIGNMENT(8) {name}_coefs_debug[{name_up}_NUM_PHASES * {name_up}_TAPS_PER_PHASE] = {{
{format_array_1d(taps_q31)}
}};

/** q30 coefficients to use for the ff3 48 - 16 kHz polyphase FIR filtering */
const int32_t ALIGNMENT(8) {name}_coefs[{name_up}_NUM_PHASES][{name_up}_TAPS_PER_PHASE] = {{
{format_array_2d(coefs_q30)}}};

"""
    _write(Path(output_dir) / f"{name}_coefs.h", header)
    _write(Path(output_dir) / f"{name}_coefs.c", source)


def write_rat_files(output_dir, coefs_ds_q30, coefs_us_q30, cmd, years="2023-2026"):
    """Write ``src_rat_fir_coefs.h`` and ``src_rat_fir_coefs.c`` for the VPU 3/2 SRC."""
    phases_ds, tph_ds = np.shape(coefs_ds_q30)
    phases_us, tph_us = np.shape(coefs_us_q30)
    num_taps = phases_ds * tph_ds
    assert num_taps == phases_us * tph_us
    banner = AUTOGEN_BANNER.format(cmd=cmd)

    header = f"""\
{_copyright(years)}

{banner}

#pragma once

#include <stdint.h>

{ALIGNMENT_MACRO}

#define SRC_RAT_FIR_NUM_TAPS ({num_taps})
#define SRC_RAT_FIR_NUM_PHASES_DS ({phases_ds})
#define SRC_RAT_FIR_TAPS_PER_PHASE_DS ({tph_ds})
#define SRC_RAT_FIR_NUM_PHASES_US ({phases_us})
#define SRC_RAT_FIR_TAPS_PER_PHASE_US ({tph_us})

/** q30 coefficients to use for the 48 -> 32 kHz polyphase rational factor downsampling */
extern const int32_t src_rat_fir_ds_coefs[SRC_RAT_FIR_NUM_PHASES_DS][SRC_RAT_FIR_TAPS_PER_PHASE_DS];

/** q30 coefficients to use for the 32 -> 48 kHz polyphase rational factor upsampling */
extern const int32_t src_rat_fir_us_coefs[SRC_RAT_FIR_NUM_PHASES_US][SRC_RAT_FIR_TAPS_PER_PHASE_US];

"""

    source = f"""\
{_copyright(years)}

{banner}

#include "src_rat_fir_coefs.h"
#include <stdint.h>

/** q30 coefficients to use for the 48 -> 32 kHz polyphase rational factor downsampling */
const int32_t ALIGNMENT(8) src_rat_fir_ds_coefs[SRC_RAT_FIR_NUM_PHASES_DS][SRC_RAT_FIR_TAPS_PER_PHASE_DS] = {{
{format_array_2d(coefs_ds_q30)}
}};

/** q30 coefficients to use for the 32 -> 48 kHz polyphase rational factor upsampling */
const int32_t ALIGNMENT(8) src_rat_fir_us_coefs[SRC_RAT_FIR_NUM_PHASES_US][SRC_RAT_FIR_TAPS_PER_PHASE_US] = {{
{format_array_2d(coefs_us_q30)}
}};

"""
    _write(Path(output_dir) / "src_rat_fir_coefs.h", header)
    _write(Path(output_dir) / "src_rat_fir_coefs.c", source)


def write_legacy_ff3v_files(output_dir, legacy, cmd, years="2016-2026"):
    """
    Write ``src_ff3v_fir.h`` and ``src_ff3v_fir.xc`` for the deprecated
    src_ds3_voice/src_us3_voice functions. ``legacy`` is the dict returned by
    ``design.legacy_ff3v_coefs``.
    """
    num_phases, taps_per_phase = np.shape(legacy["coefs"])

    header = f"""\
{_copyright(years)}
//
// This file is generated using lib_src.voice.generate
// {cmd}
//
// Do not modify it directly, changes may be overwritten!
//

#pragma once

#include <stdint.h>

#define SRC_FF3V_FIR_NUM_PHASES ({num_phases})
#define SRC_FF3V_FIR_TAPS_PER_PHASE ({taps_per_phase})

extern const unsigned src_ff3v_fir_comp_q_ds;
extern const int32_t src_ff3v_fir_comp_ds;

extern const unsigned src_ff3v_fir_comp_q_us;
extern const int32_t src_ff3v_fir_comp_us;

extern int32_t src_ff3v_fir_coefs_debug[SRC_FF3V_FIR_NUM_PHASES * SRC_FF3V_FIR_TAPS_PER_PHASE];

#if defined(__XC__)
extern const int32_t (*src_ff3v_fir_coefs_xc)[SRC_FF3V_FIR_TAPS_PER_PHASE];
#define src_ff3v_fir_coefs src_ff3v_fir_coefs_xc
#else
extern const int32_t (*src_ff3v_fir_coefs_c)[SRC_FF3V_FIR_TAPS_PER_PHASE];
#define src_ff3v_fir_coefs src_ff3v_fir_coefs_c
#endif
"""

    source = f"""\
{_copyright(years)}
//
// This file is generated using lib_src.voice.generate
// {cmd}
//
// Do not modify it directly, changes may be overwritten!
//

#include "src_ff3v_fir.h"
#include <stdint.h>

/** Used for FIR compensation for decimation*/
const unsigned src_ff3v_fir_comp_q_ds = {legacy["comp_q_ds"]};

/** Used for FIR compensation for decimation*/
const int32_t src_ff3v_fir_comp_ds = {legacy["comp_ds"]};

/** Used for FIR compensation for upsampling*/
const unsigned src_ff3v_fir_comp_q_us = {legacy["comp_q_us"]};

/** Used for FIR compensation for upsampling*/
const int32_t src_ff3v_fir_comp_us = {legacy["comp_us"]};

/** Used for self testing src_ds3_voice and src_us3_voice functionality */
int32_t src_ff3v_fir_coefs_debug[SRC_FF3V_FIR_NUM_PHASES * SRC_FF3V_FIR_TAPS_PER_PHASE] = {{
{format_array_1d(legacy["coefs_debug"])}
}};

/** Coefficients for use with src_ds3_voice and src_us3_voice functions */
static const int32_t [[aligned(8)]] src_ff3v_fir_coefs_i[SRC_FF3V_FIR_NUM_PHASES][SRC_FF3V_FIR_TAPS_PER_PHASE] = {{
{format_array_2d(legacy["coefs"])}}};

unsafe {{
    const int32_t (* unsafe src_ff3v_fir_coefs_c)[SRC_FF3V_FIR_TAPS_PER_PHASE] = src_ff3v_fir_coefs_i;
}}

const int32_t (*src_ff3v_fir_coefs_xc)[SRC_FF3V_FIR_TAPS_PER_PHASE] = src_ff3v_fir_coefs_i;
"""
    _write(Path(output_dir) / "src_ff3v_fir.h", header)
    _write(Path(output_dir) / "src_ff3v_fir.xc", source)


def _write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w") as f:
        f.write(text)
